#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_gh_stubs.sh. The two halves of the stub contract are
# each reddened on their own, so a half-wired self-test cannot pass: the chmod
# that makes the stub visible to `command -v`, and the GH_BIN that names it ahead
# of the box's own `gh`. A self-test with no stub and a missing tests dir answer
# 0 and 125 respectively.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_gh_stubs.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-gh-stubs-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

failures=0
check() { # name want got
    if [ "$2" = "$3" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$3"
    else
        printf 'FAIL  %s: want rc %s, got rc %s\n' "$1" "$2" "$3"
        failures=$((failures + 1))
    fi
}

write_full() { # dir — the wired pair, as 8c37ea6 shipped it
    cat >"$1/complete_test.sh" <<'FIX'
#!/usr/bin/env bash
cat >"$SANDBOX/gh" <<'STUB'
#!/usr/bin/env bash
exit 0
STUB
chmod 755 "$SANDBOX/gh"
run_gate() {
    ( cd "$ROOT" && PATH="$SANDBOX:$PATH" GH_BIN="$SANDBOX/gh" bash "$GATE" ) >/dev/null 2>&1
    printf '%s' "$?"
}
FIX
}

run_gate() { # dir
    [ -d "$1/.git" ] || ( cd "$1" && git init -q . ) >/dev/null 2>&1
    ( cd "$1" && bash "$GATE" tests ) >/dev/null 2>&1
    printf '%s' "$?"
}

# 1. Both halves present.
d="$SANDBOX/full"; mkdir -p "$d/tests"; write_full "$d/tests"
check "stub chmod-ed and named" 0 "$(run_gate "$d")"

# 2. The mode-bit half missing: the 644 stub that reddened the runner.
sed -i '/^chmod 755 /d' "$d/tests/complete_test.sh"
check "stub left at 644" 1 "$(run_gate "$d")"

# 3. The chmod back, GH_BIN gone: PATH order decides the answerer.
write_full "$d/tests"
sed -i 's/GH_BIN="\$SANDBOX\/gh" //' "$d/tests/complete_test.sh"
check "GH_BIN not naming the stub" 1 "$(run_gate "$d")"

# 4. GH_BIN naming something else than the stub.
write_full "$d/tests"
sed -i 's/GH_BIN="\$SANDBOX\/gh"/GH_BIN=gh/' "$d/tests/complete_test.sh"
check "GH_BIN naming the system gh" 1 "$(run_gate "$d")"

# 5. `chmod +x` is as good as 755.
write_full "$d/tests"
sed -i 's/^chmod 755 /chmod +x /' "$d/tests/complete_test.sh"
check "chmod +x accepted" 0 "$(run_gate "$d")"

# 6. A self-test with no stub is not the gate's business.
d2="$SANDBOX/nostub"; mkdir -p "$d2/tests"
printf '#!/usr/bin/env bash\necho Self-test passed\n' >"$d2/tests/plain_test.sh"
check "no stub anywhere" 125 "$(run_gate "$d2")"

# 7. No tests dir at all.
mkdir -p "$SANDBOX/bare"
( cd "$SANDBOX/bare" && git init -q . ) >/dev/null 2>&1
check "no tests dir" 125 "$( cd "$SANDBOX/bare" && bash "$GATE" tests >/dev/null 2>&1; printf '%s' "$?" )"

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
